def acquisition_mask(times, windows_ns):
    w = np.asarray(windows_ns, dtype=np.float64).reshape(-1, 2)
    if not np.isfinite(w).all() or np.any(w[:, 0] >= w[:, 1]):
        raise ValueError("Acquisition windows must be finite and ordered")
    if np.any(w[1:, 0] < w[:-1, 1]):
        raise ValueError("Merge overlapping acquisition windows first")
    accepted = np.zeros(np.shape(times), dtype=bool)
    for start, stop in w:
        accepted |= (times >= start) & (times < stop)
    return accepted

